using System;using System.Linq;using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;
public static class OptimizeCampusRooms {public static object Run(){if(EditorApplication.isPlaying)throw new Exception("Edit Mode required");var report=new System.Collections.Generic.List<object>();foreach(var room in GameObject.Find("School expansion").transform.Cast<Transform>().Where(t=>t.name.EndsWith(" - environment only"))){var rs=room.GetComponentsInChildren<Renderer>();var architecture=rs.Where(r=>new[]{"Wall","Floor","Ceiling","Door","Window","Glass","BlackBoard","Blackboard","Chalkboard","WoodBorder"}.Any(n=>r.name.IndexOf(n,StringComparison.OrdinalIgnoreCase)>=0)).ToArray();var lod=room.GetComponent<LODGroup>();if(!lod)lod=room.gameObject.AddComponent<LODGroup>();lod.SetLODs(new[]{new LOD(.38f,rs),new LOD(0,architecture)});lod.RecalculateBounds();report.Add(new{room=room.name,full=rs.Length,distant=architecture.Length,size=lod.size});}EditorSceneManager.MarkSceneDirty(EditorSceneManager.GetActiveScene());EditorSceneManager.SaveScene(EditorSceneManager.GetActiveScene());return report;}}
